function editCrown(id){const c=state.crowns.find(c=>c.id===id)||{},tier=state.settings.tiers.find(t=>t.name===c.tier)||state.settings.tiers[0];modal('👑 冠歌管理',`<div class="form-grid">${select('playerId','冠歌主人',playerOptions(),c.playerId)}${select('songId','歌曲',state.songs.map(s=>[s.songId,s.title+'－'+s.artist]),c.songId)}${select('tier','卡別',state.settings.tiers.map(t=>t.name),tier.name)}${field('fee','辦卡給歌手',c.fee??tier.fee,'number','min="0"')}${field('price','其他玩家現點',c.price??tier.price,'number','min="0"')}${field('double','辦卡雙費（每人）',c.double??state.settings.crownDouble,'number','min="0"')}${field('months','期限月數（0＝永久）',c.months??tier.months,'number','min="0"')}${area('note','備註',c.note||'')}</div>${c.activatedAt?`<div class="notice">生效：${time(c.activatedAt)}<br>到期：${c.expiresAt?time(c.expiresAt):'永久'}</div>`:`<div class="notice">先存為待確認；三筆款項齊了，再勾選生效。</div>${check('singerPaid','已收到辦卡給歌手費用')}${check('bandPaid','已收到聲瑪樂團費用')}${check('hostPaid','已收到2號位主持費用')}${check('activate','確認現在生效，從現在開始計算期限')}`}${c.id?button('刪除冠歌','deleteCrown',c.id,'tiny danger'):''}`,async f=>dispatch('crown',{...formData(f),id:c.id,activate:f.has('activate'),singerPaid:f.has('singerPaid'),bandPaid:f.has('bandPaid'),hostPaid:f.has('hostPaid')}));$('#dialog select[name=tier]').onchange=e=>{const t=state.settings.tiers.find(t=>t.name===e.target.value);for(const k of ['fee','price','months'])$('#dialog [name='+k+']').value=t[k];};}
async function compress(file,max=1400){if(!file||!file.type.startsWith('image/'))throw new Error('請選圖片');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/webp',.82).split(',')[1];}
function editCard(id){const c=state.cards.find(c=>c.id===id)||{};modal('🖼️ 照片卡片',`${field('file','上傳照片（自動壓縮、縮圖）','','file','accept="image/*"')}${select('playerId','綁定玩家（選填）',[['','不綁定'],...playerOptions().slice(1)],c.playerId)}${area('description','簡述',c.description||'')}${field('startsAt','開始時間',dateInput(c.startsAt||clock()),'datetime-local','required')}${field('expiresAt','到期時間（留空永久）',dateInput(c.expiresAt),'datetime-local')}`,async f=>{let url=c.url,thumbnail=c.thumbnail;const file=f.get('file');if(file?.size){if(demo)throw new Error('圖片上傳需連接 Supabase，預覽不存 Base64 圖片');url=(await api({op:'upload',image:await compress(file),mime:'image/webp'})).url;thumbnail=(await api({op:'upload',image:await compress(file,480),mime:'image/webp'})).url;}await dispatch('card',{id:c.id,url,thumbnail,playerId:f.get('playerId'),description:f.get('description'),startsAt:isoInput(f.get('startsAt')),expiresAt:isoInput(f.get('expiresAt'))});});}
