function bulkSongData(f,ids){const data={songIds:ids,tagMode:f.get('tagMode'),tags:[...f.getAll('tags'),...list(f.get('customTags'))]};for(const k of ['cat','artistType'])if(f.get(k))data[k]=f.get(k);if(f.get('creditCost'))data.creditCost=Number(f.get('creditCost'));if(f.get('new'))data.new=f.get('new')==='true';if(f.get('murmurMode')!=='keep')data.murmur=f.get('murmurMode')==='clear'?'':f.get('murmur');return data;}
function updateBulkPreview(form,ids){const f=new FormData(form);if((f.getAll('tags').length||f.get('customTags').trim())&&f.get('tagMode')==='keep'){form.elements.tagMode.value='add';f.set('tagMode','add');}const d=bulkSongData(f,ids),parts=[];if(d.tagMode!=='keep')parts.push(({add:'加上標籤：',remove:'移除標籤：',replace:'改成標籤：',clear:'清空標籤'})[d.tagMode]+(d.tagMode==='clear'?'':d.tags.join('、')));if(d.creditCost)parts.push('扣歌首數：'+d.creditCost);if(d.cat)parts.push('語言：'+d.cat);if(d.artistType)parts.push('歌手分類：'+d.artistType);if('new'in d)parts.push(d.new?'設為新練歌曲':'取消新練');if('murmur'in d)parts.push(d.murmur?'碎碎念：'+d.murmur:'清空碎碎念');$('#batch-preview').textContent=parts.length?'將修改 '+ids.length+' 首：'+parts.join('；'):'尚未指定修改項目';}
