function catalogReviewHtml(){
 const sections=[['pending','待我審核'],['confirmed','已確認歌曲'],['approved','版本關係'],['templates','設定'],['history','變更紀錄']];
 const tabs=`<div class="tabs">${sections.map(([key,label])=>button(label,'catalogSection',key,catalogView.section===key?'active':'')).join('')}</div>`;
 if(catalogView.section==='templates')return tabs+catalogTemplateHtml();
 if(catalogView.section==='confirmed')return tabs+'<p>共同歌曲只保留全站主資料，主播各自的歌本與設定獨立。</p>'+button('查看／管理已確認歌曲','catalogConfirmed','','primary');
 const rows=catalogView.items||[],status=catalogView.section,reviewable=['pending','approved'].includes(status);
 const rowHtml=row=>{
  const roomLabel=id=>state.streamers.find(r=>r.id===id)?.display_name||id||'';
  const labels={approve_new:'建立共同歌曲',link_variant:'關聯共同版本',create_variant:'建立新版本',reject:'拒絕候選',remove:'移除候選',unlink:'解除共同關聯',update_variant:'更新共同主資料',merge_family:'調整作品群組',split_variant:'拆分共同版本',language_filter:'更新語言篩選',lyric_save:'儲存共同歌詞',lyric_choice:'更新主播歌詞',batch_add:'批量加入歌本',template_change:'更新模板'};
  const id=String(row.candidateId||row.id||''),name=status==='history'?eventDescription(row,{playerName,songName:id=>song(id)?.title,roomName:roomLabel}):[row.title,row.artist].filter(Boolean).join('｜'),suggestions=(row.suggestedVariants||[]).slice(0,3).map(x=>[x.title,x.artist,x.versionLabel].filter(Boolean).join(' · ')).join('；');
  const peers=(row.suggestedCandidates||[]).slice(0,3).map(x=>[({possible_same:'疑似同曲',possible_version:'可能不同版本',same_title:'僅同名'})[x.matchType]||'待比較',x.title,x.artist,roomLabel(x.streamerId),x.language,x.versionLabel].filter(Boolean).join(' · ')).join('；');
  const actorLabel=row.actorId==='president'?'PA Party總裁':row.actorId?.startsWith('streamer:')?roomLabel(row.actorId.slice(9)):row.actorId;
  return `<div class="song catalog-row">${reviewable?`<label class="catalog-check"><input type="checkbox" data-catalog-review="${h(id)}" ${catalogView.selected.has(id)?'checked':''} aria-label="選取 ${h(name)}"></label>`:''}<div class="info"><b>${h(name||'待審歌曲')}</b><small>${h([row.streamerName||roomLabel(row.streamerId),row.language,row.performerType,row.variantLabel||row.versionLabel].filter(Boolean).join(' · '))}</small>${suggestions?`<small>可能相關：${h(suggestions)}</small>`:''}${peers?`<small>候選比較：${h(peers)}</small>`:''}${status==='approved'&&row.variantId?'<div class="actions">'+button('編輯','relationEdit',id)+button('查看主播','relationRooms',id)+button('刪除共同版本','relationDelete',id,'tiny danger')+'</div>':''}${status==='history'?`<small>${h([actorLabel,time(row.createdAt||row.at||row.created_at)].filter(Boolean).join(' · '))}</small><details><summary>技術詳情</summary><pre>${h(JSON.stringify(row,null,2))}</pre></details>`:''}</div></div>`;
 };const groups=new Map();for(const row of rows){const key=catalogGroupKey(row);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}const single=[...groups.values()].filter(g=>g.length===1&&!g[0].suggestedCandidates?.length),duplicates=[...groups.values()].filter(g=>g.length>1||g[0].suggestedCandidates?.length);const entries=(status==='pending'?'<h3>單筆待審 · 可多選批次通過</h3>'+single.map(g=>'<section class="catalog-single-candidate">'+g.map(rowHtml).join('')+'</section>').join('')+(single.length?'':blank('本頁沒有單筆待審'))+'<h3>疑似重複 · 兩筆以上來源比較</h3>'+duplicates.map(group=>'<section class="catalog-candidate-group"><h3>'+h(group[0].title)+'</h3><div class="actions">'+button('確認是同一首','catalogReviewSame',group[0].id)+button('同一首，但不同版本','catalogReviewGroupVersion',group[0].id)+button('不是同一首','catalogReviewGroupReject',group[0].id)+'</div>'+group.map(rowHtml).join('')+'</section>').join('')+(duplicates.length?'':blank('本頁沒有疑似重複')):rows.map(rowHtml).join(''))||blank(catalogView.loading?'正在讀取…':'這一頁沒有資料');
 const actions=status==='pending'?`<div class="actions">${button('批次通過單筆待審','catalogReviewAction','approve_new','',''+(catalogView.selected.size?'':'disabled'))}${button('不是同一首','catalogReviewAction','reject','tiny danger',catalogView.selected.size?'':'disabled')}<small>暫不處理的候選保留待審</small></div>`:status==='approved'?`<div class="actions">${button('從共同曲庫分開','catalogReviewAction','unlink','tiny danger',catalogView.selected.size?'':'disabled')+button('拆為另一個版本','catalogSplit','','tiny',catalogView.selected.size?'':'disabled')}</div>`:'';
 const nav=catalogPager(catalogView,'catalogPage');
 return tabs+`<div class="toolbar"><input id="catalog-review-search" type="search" placeholder="篩選待審歌名、歌手" value="${h(catalogView.search||'')}">${button('搜尋','catalogFilter')}${button('選取本頁','catalogSelectPage')}${button('選取目前篩選結果全部 '+catalogView.total+' 筆','catalogSelectAll')}${button('取消選取','catalogClear')}<b>已選 ${catalogView.selected.size} 筆</b></div><p class="muted">既有主播歌本不會因共同曲庫審核而被刪除或覆寫；核准前只建立候選。</p>${actions}${catalogView.error?`<p class="error">${h(catalogView.error)}</p>`:''}<div id="catalog-review-list">${entries}</div>${nav}`;
}
async function scanCatalogCandidates(){
 if(!isSuperAdmin()||catalogView.scanning)return;
 if(demo||draft)return toast('預覽模式不會掃描正式歌本');
 if(catalogView.scanComplete){catalogView.scanCursor='';catalogView.scanTotal=0;catalogView.scanComplete=false;}
 catalogView.scanning=true;render();
 try{const r=await api({op:'catalogScan',afterSongId:catalogView.scanCursor,limit:100,management:true});
  catalogView.scanTotal+=Number(r.processed)||0;catalogView.scanCursor=r.nextCursor||'';catalogView.scanComplete=!r.nextCursor;
  catalogView.loaded=false;await loadCatalogReview();toast(catalogView.scanComplete?'候選掃描完成，等待總裁審核':'本批候選已完成，可繼續掃描下一批');
 }catch(err){toast(err.message);}finally{catalogView.scanning=false;if(['catalog','settings'].includes(tab))render();}
}
function catalogTemplateHtml(){
 const data=catalogView.templates;if(!data)return `<p>${catalogView.loading?'正在讀取模板…':h(catalogView.error||'尚未載入模板')}</p>`;
 return [['language','語言',data.languages||[]],['performerType','演唱者類型',data.performerTypes||[]]].map(([kind,label,rows])=>`<h3>${label}</h3><div class="actions">${button('新增'+label,'catalogTemplateAdd',kind)}</div>${rows.map(row=>`<div class="song"><div class="info"><b>${h(row.name)}</b><small>${row.active===false?'已停用':'使用中'}</small></div>${button('編輯','catalogTemplateEdit',row.id,'tiny',`data-kind="${kind}"`)}</div>`).join('')||blank()}`).join('');
}
async function loadCatalogReview(){
 if(!isSuperAdmin()||tab!=='catalog'||catalogView.loading)return;
 if(catalogView.section==='confirmed'){catalogView.loaded=true;render();return;}
 if(demo||draft){catalogView.error='預覽模式不會寫入正式共同曲庫';catalogView.loaded=true;render();return;}
 catalogView.loading=true;catalogView.error='';
 const section=catalogView.section,page=catalogView.page,size=catalogView.pageSize||20,query=catalogView.search||'';
 const current=()=>isSuperAdmin()&&tab==='catalog'&&catalogView.section===section&&catalogView.page===page&&(catalogView.pageSize||20)===size&&(catalogView.search||'')===query;
 try{const response=section==='templates'?await api({op:'catalogTemplates',management:true}):await api({op:'catalogReviewList',status:section,limit:size,offset:page*size,q:query,management:true});
  if(!current())return;
  if(section==='templates')catalogView.templates=response;
  else{catalogView.items=response.items||[];catalogView.total=response.total||0;catalogView.hasMore=!!response.hasMore;}
  catalogView.loaded=true;
 }catch(err){if(current()){catalogView.error=err.message;catalogView.loaded=true;}}finally{catalogView.loading=false;if(tab==='catalog')render();}
}
async function catalogReviewAction(decision,ids=[...catalogView.selected],target={}){
 if(!isSuperAdmin()||!ids.length)return toast('請先選擇待審歌曲');
 if(!['confirm_same','approve_new','link_variant','create_variant','reject','remove','unlink'].includes(decision))return;
 if(demo||draft)throw Error('請在正式管理端審核');
 const label=({confirm_same:'確認是同一首共同歌曲',approve_new:'建立共同歌曲',link_variant:'關聯既有版本',create_variant:'建立新版本',reject:'拒絕',remove:'移除候選',unlink:'解除共同關聯'})[decision];
 const expectedSources=Object.fromEntries(ids.map(id=>[id,catalogView.selectedSources.get(id)]));
 if(Object.values(expectedSources).some(value=>!value))throw Error('選取的候選資料已更新，請重新選取後審核');
 if(!confirm(`${label} ${ids.length} 首？主播原歌本與歷史紀錄會保留。`))return;
 let variantId=target.variantId;for(let i=0;i<ids.length;i+=50){const batch=ids.slice(i,i+50);const response=await api({op:'catalogReview',decision:decision==='confirm_same'&&i>0?'link_variant':decision,candidateIds:batch,expectedSources:Object.fromEntries(batch.map(id=>[id,expectedSources[id]])),...target,...(variantId?{variantId}:{}),management:true});variantId=response?.variantId||variantId;for(const id of batch){catalogView.selected.delete(id);catalogView.selectedRows.delete(id);catalogView.selectedSources.delete(id);catalogView.selectedVariants.delete(id);}}
 catalogView.selected.clear();catalogView.selectedSources.clear();catalogView.selectedVariants?.clear();catalogView.loaded=false;await loadCatalogReview();toast(`已${label} ${ids.length} 首`);
}
