async function relationRoomsPage(id,offset){const r=await api({op:"catalogRooms",variantId:id,limit:50,offset,management:true});modal("使用此共同版本的主播",(r.items||[]).map(x=>"<div class=\"song\">"+h(state.streamers.find(z=>z.id===x.streamerId)?.display_name||x.streamerId)+" · "+h(x.title)+"－"+h(x.artist)+"</div>").join("")+(offset?button("上一頁主播","relationRoomsPage",id,"tiny",`data-offset="${Math.max(0,offset-50)}"`):"")+(r.hasMore?button("查看下一頁主播","relationRoomsPage",id,"tiny",`data-offset="${offset+50}"`):""));}

setInterval(()=>{for(const node of document.querySelectorAll("[data-preparation]")){const q=state.queue.find(x=>x.id===node.dataset.preparation);if(q&&["pending","waiting"].includes(q.status))node.textContent=queuePreparation(q,clock());}},1000);

async function loadCandidateGroup(id){const seed=catalogView.items.find(x=>String(x.id)===id);if(!seed)return [];if(demo||draft)return catalogView.items.filter(x=>catalogGroupKey(x)===catalogGroupKey(seed));const list=[];for(let offset=0;offset<=10000;offset+=50){const r=await api({op:"catalogReviewList",status:"pending",q:seed.title,limit:50,offset,management:true});list.push(...(r.items||[]).filter(x=>catalogGroupKey(x)===catalogGroupKey(seed)));if(!r.hasMore)break;}catalogView.selected.clear();catalogView.selectedRows.clear();catalogView.selectedSources.clear();catalogView.selectedVariants.clear();selectCatalogRows(list);return list;}
